{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 10^6",
      "description": "The length of the binary strings is between 1 and 10^6."
    },
    {
      "id": "P2",
      "expression": "len(s) == n and len(t) == n",
      "description": "Both strings s and t have the same length n."
    },
    {
      "id": "P3",
      "expression": "all(c in '01' for c in s) and all(c in '01' for c in t)",
      "description": "Both strings s and t consist only of the characters '0' and '1'."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output == -1 or (1 <= output <= n)",
      "description": "The output is either -1 if it is impossible to convert s to t, or a non-negative integer representing the minimum number of operations required."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "expression": "all(s[i] == t[i] for i in range(n))",
      "description": "The strings s and t are identical if the minimum number of operations is 0."
    },
    {
      "id": "I2",
      "expression": "all(s[i] == t[i] or s[i] == '0' and t[i] == '1' or s[i] == '1' and t[i] == '0' for i in range(n))",
      "description": "The characters at each position in s and t are either the same or one can be obtained from the other by flipping a single bit."
    }
  ]
}
